vec4 multiply(vec4 v, mat4 m) { return m * v; }
vec4 textureBias(sampler2D s, vec4 uv4) { return textureLod(s, uv4.xy, uv4.w); }
vec4 textureLod4(sampler2D s, vec4 uv4) { return textureLod(s, uv4.xy, uv4.w); }
vec3 ret1, neu;
vec2 uv2,uv3;
shader_body
{
vec2 uv2;
float ang2, c, s;
uv -= 0.5;
uv *= uAspect.xy;
uv = multiply(uv, mat2(_qb));
float dist = 1;
float inten = 1;
ret1 = 0;
int anz = 4;
float n = anz;
while (n >= 0) {
ang2 = 0.0 * n/anz;
c = cos(ang2);
s = sin(ang2);
uv2.x =  uv.x*c - uv.y*s;
uv2.y =  uv.x*s + uv.y*c;
//uv2 = uv;
dist = 1.0 - fract(1.0/anz*n+q30); //evtl sqrt !
inten =  sqrt(dist)*(1.0 - dist) * 2.0;
vec2 uv3 = 3.0 * uv2*dist*(1.0 + q5*uv.x) + 0.5 +vec2(q18*n,q19) ;
vec3 cmul = vec3(dist,1.0 - dist,1.0 - (dist-.5)*(dist-.5) * 4.0);
neu = texture(sampler_main,uv3) +q6*GetBlur1(fract(uv3*1.04)).bgr * 1.0;
//    neu = neu*cmul;
ret1 = max(ret1,neu*inten);
n--;
}
ret1 = mix(ret1,ret1.gbr,q26 / 6.0);
ret = ret1 * 2.0 + (1.0 - rad)*q26 / 3.0*GetPixel(q5 / 2.0+uv*(2.0 - rad));
}

